<?php $t=PortableRecords::target($target);$columns=array_keys($rows[0]); ?><h1><?= e(t('Map columns to')) ?> <?= e($t['label']) ?></h1><section class="card"><p><?= count($rows) ?> <?= e(t('rows. Dates must use YYYY-MM-DD. Blank optional fields are allowed; no record is saved yet.')) ?></p><form class="form-grid" method="post" action="/platform/records/preview"><?= csrf_field() ?><?php foreach($t['fields']as $field): ?><label><?= e(ucfirst(str_replace('_',' ',$field))) ?><select name="mapping[<?= e($field) ?>]"><option value=""><?= e(t('Leave blank')) ?></option><?php if($field==='module_id'): ?><option value="__module" selected><?= e(t('Use selected University module')) ?></option><?php endif; ?><?php foreach($columns as $column): ?><option value="<?= e($column) ?>" <?= $column===$field?'selected':'' ?>><?= e($column) ?></option><?php endforeach; ?></select></label><?php endforeach; ?><?php if(in_array('module_id',$t['fields'],true)): ?><label><?= e(t('University module')) ?><select name="module_id"><option value=""><?= e(t('Map a module column instead')) ?></option><?php foreach(Db::all('SELECT id,code,name FROM uni_modules ORDER BY name')as $m): ?><option value="<?= e($m['id']) ?>"><?= e($m['code'].' · '.$m['name']) ?></option><?php endforeach; ?></select></label><?php endif; ?><button><?= e(t('Validate & preview')) ?></button></form></section>
